arguments.command:
# Force 1Password operator resync of the item
kubectl patch onepassworditem github-org-token -n arc-runners --type=merge -p='{ "metadata": { "annotations": { "resync": "true" } } }' 2>&1

# Now wait for sync (might take up to 3 minutes based on polling interval)
sleep 5

check_secret() {
    secret_exists=$(kubectl get secret -n arc-runners github-org-token 2>/dev/null) && echo "Secret exists:" && kubectl get secret -n arc-runners github-org-token -o jsonpath='{.data.github_token}' 2>&1 | head -1
    return $([ $? -eq 0 ] && echo "$secret_exists" | grep -q github-org-token)
}

echo "Checking if secret was recreated..."
kubectl get secret -n arc-runners github-org-token 2>&1 || echo "Not yet synced, will wait..."

